-- Evita que PUBLIC/anon herde EXECUTE de funções administrativas.
revoke execute on function public.admin_listar_usuarios(text,boolean,text), public.admin_listar_solicitacoes_acesso(text), public.admin_atualizar_usuario(integer,jsonb,jsonb), public.admin_revisar_solicitacao_acesso(uuid,boolean,text,text[],integer,uuid,uuid,text) from public, anon;
grant execute on function public.admin_listar_usuarios(text,boolean,text), public.admin_listar_solicitacoes_acesso(text), public.admin_atualizar_usuario(integer,jsonb,jsonb), public.admin_revisar_solicitacao_acesso(uuid,boolean,text,text[],integer,uuid,uuid,text) to authenticated;
revoke execute on function public.aprovar_solicitacao_acesso(uuid,text,text[],integer,uuid,uuid,text), public.rejeitar_solicitacao_acesso(uuid,text), public.compras_solicitar_estorno(integer,jsonb,text), public.compras_aprovar_estorno(bigint,boolean,text), public.compras_encerrar_pedido(integer,text), public.fn_proteger_usuario_autogerenciado() from public, anon;
grant execute on function public.aprovar_solicitacao_acesso(uuid,text,text[],integer,uuid,uuid,text), public.rejeitar_solicitacao_acesso(uuid,text), public.compras_solicitar_estorno(integer,jsonb,text), public.compras_aprovar_estorno(bigint,boolean,text), public.compras_encerrar_pedido(integer,text) to authenticated;
